css:
@import url("https://fonts.googleapis.com/css2?family=Pacifico&family=DM+Sans:wght@400;500;700&display=swap");
:root{--bg:#F1EFE7;--card:#fff;--ink:#1F2A2E;--mu:#5C686B;--tl:#1B998B;--tl2:#157A6F;--my:#E9C46A;--ln:#E1DED3;--h:"Pacifico",cursive;--b:"DM Sans",system-ui,sans-serif}
[data-theme=dark]{--bg:#12211F;--card:#1B2E2B;--ink:#EEF3F1;--mu:#A9BDB8;--ln:#2C4540}
*,*::before,*::after{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.55;color:var(--ink);background:var(--bg);min-height:100vh;transition:background .3s,color .3s}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1{font-family:var(--h);font-weight:400;margin:0;line-height:1.2}
.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--my);padding:8px;z-index:99}:focus-visible{outline:3px solid var(--my);outline-offset:3px}
.col{max-width:480px;margin:0 auto;padding:18px 18px 40px}
.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.top button{width:44px;height:44px;border-radius:50%;border:1px solid var(--ln);background:var(--card);color:var(--ink);cursor:pointer;font-size:18px}
.burger{display:none}.nav-hidden{display:none}
.pf{text-align:center;padding:10px 0 20px}.av{width:112px;height:112px;border-radius:50%;margin:0 auto 14px;object-fit:cover;border:4px solid var(--my)}
.pf h1{font-size:32px;color:var(--tl)}[data-theme=dark] .pf h1{color:var(--my)}.pf p{color:var(--mu);margin:6px auto 0;max-width:22em}
.soc{display:flex;justify-content:center;gap:10px;margin:16px 0 0}.soc a{width:44px;height:44px;border-radius:50%;background:var(--card);border:1px solid var(--ln);display:grid;place-items:center}
.drop{background:var(--tl);color:#fff;border-radius:22px;padding:18px;margin:18px 0;display:grid;grid-template-columns:84px 1fr;gap:14px;align-items:center}.drop img{width:84px;height:84px;border-radius:16px;object-fit:cover}
.drop small{color:#CFEDE8;font-weight:500}.drop b{display:block;font-size:19px;margin:2px 0}.drop .cd{font-weight:700;color:var(--my)}
.links{list-style:none;padding:0;margin:0;display:grid;gap:10px}.links a{display:flex;align-items:center;gap:12px;background:var(--card);border:1px solid var(--ln);border-radius:18px;padding:14px 16px;text-decoration:none;font-weight:500;transition:transform .15s}.links a:hover{transform:translateY(-2px)}
.links .ic{width:40px;height:40px;border-radius:12px;background:var(--bg);display:grid;place-items:center;flex:none;font-size:18px}.links span.t{flex:1}.links small{display:block;color:var(--mu);font-weight:400;font-size:14px}
.links a.hl{background:var(--my);border-color:var(--my);color:#1F2A2E}.links a.hl small{color:#5A4A1A}
.nl{background:var(--card);border:1px solid var(--ln);border-radius:22px;padding:18px;margin-top:18px}.nl b{display:block;margin-bottom:8px}.nl form{display:flex;gap:8px}.nl input{flex:1;min-width:0;font:16px var(--b);padding:12px 14px;border:1px solid var(--ln);border-radius:30px;background:var(--bg);color:var(--ink)}.nl label{position:absolute;left:-999px}
.nl button,.share button{font:700 15px var(--b);background:var(--tl);color:#fff;border:0;border-radius:30px;padding:12px 16px;cursor:pointer}
.share{display:flex;gap:8px;justify-content:center;margin-top:18px;flex-wrap:wrap}.share button{background:var(--card);color:var(--ink);border:1px solid var(--ln)}
.msg{visibility:hidden;text-align:center;font-size:15px;color:var(--tl);font-weight:500;margin:10px 0 0;min-height:22px}.msg.on{visibility:visible}[data-theme=dark] .msg{color:var(--my)}
footer{text-align:center;font-size:14px;color:var(--mu);padding:10px 18px 30px}
@media (prefers-reduced-motion:reduce){*{transition:none!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);const say=t=>{$('msg').textContent=t;$('msg').classList.add('on')};
$('th').onclick=()=>{const d=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=d?'dark':'light';$('th').textContent=d?'☀':'☾';$('th').setAttribute('aria-pressed',d);$('th').setAttribute('aria-label',d?'Switch to light mode':'Switch to dark mode')};
const D=new Date();D.setDate(D.getDate()+((5-D.getDay()+7)%7||7));D.setHours(18,0,0,0);
function cd(){const s=Math.max(0,Math.floor((D-new Date())/1000));$('cd').textContent=`Opens in ${Math.floor(s/86400)}d ${Math.floor(s%86400/3600)}h ${Math.floor(s%3600/60)}m, Friday 6pm`}cd();setInterval(cd,30000);
const url=location.href.split('#')[0];$('cp').onclick=()=>{(navigator.clipboard?navigator.clipboard.writeText(url):Promise.reject()).then(()=>say('Link copied. Paste it anywhere.')).catch(()=>say('Copy this link: '+url))};
$('sh').onclick=()=>{if(navigator.share)navigator.share({title:'Rosa Mendes Ceramics',url}).catch(()=>{});else say('Sharing is not supported here. Use "Copy my link" instead.')};
$('nf').onsubmit=e=>{e.preventDefault();say("You're in! I'll email you the day before each drop.");$('ne').value=''};
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
